

module clockhdr
(
  TE,
  E,
  CP,
  Q
);

  input TE;
  input E;
  input CP;
  output Q;

  // wire Q,enable,N0;
  // reg en_ff;

  // always @(enable or N0) begin
  //   if(N0) begin
  //     en_ff <= enable;
  //   end
  // end

  // assign enable = E | TE;
  // assign N0 = ~CP;
  // assign Q = CP & en_ff;

  wire enable;
  assign enable = E | TE;

OPENROAD_CLKGATE clkgate (
  .CK (CP),
  .E  (enable),
  .GCK(Q)
);


endmodule



module rvclkhdr
(
  en,
  clk,
  scan_mode,
  l1clk
);

  input en;
  input clk;
  input scan_mode;
  output l1clk;
  wire l1clk;

  clockhdr
  rvclkhdr
  (
    .TE(scan_mode),
    .E(en),
    .CP(clk),
    .Q(l1clk)
  );


endmodule



module rvdff_WIDTH1
(
  din,
  clk,
  rst_l,
  dout
);

  input [0:0] din;
  output [0:0] dout;
  input clk;
  input rst_l;
  wire N0;
  reg [0:0] dout;

  always @(posedge clk or posedge N0) begin
    if(N0) begin
      dout[0] <= 1'b0;
    end else if(1'b1) begin
      dout[0] <= din[0];
    end
  end

  assign N0 = ~rst_l;

endmodule



