    if(N0) begin
      wren[0] <= 1'b0;
    end else if(1'b1) begin
      wren[0] <= wr_en;
    end
  end


  always @(posedge clk or posedge N0) begin
    if(N0) begin
      rden[2] <= 1'b0;
    end else if(1'b1) begin
      rden[2] <= rden[1];
