module dmi_wrapper
(
  scan_mode,
  trst_n,
  tck,
  tms,
  tdi,
  tdo,
  tdoEnable,
  core_rst_n,
  core_clk,
  jtag_id,
  rd_data,
  reg_wr_data,
  reg_wr_addr,
  reg_en,
  reg_wr_en,
  dmi_hard_reset
);

  input [31:1] jtag_id;
  input [31:0] rd_data;
  output [31:0] reg_wr_data;
  output [6:0] reg_wr_addr;
  input scan_mode;
  input trst_n;
  input tck;
  input tms;
  input tdi;
  input core_rst_n;
  input core_clk;
  output tdo;
  output tdoEnable;
  output reg_en;
  output reg_wr_en;
  output dmi_hard_reset;
  wire [31:0] reg_wr_data;
  wire [6:0] reg_wr_addr;
  wire tdo,tdoEnable,reg_en,reg_wr_en,dmi_hard_reset,rd_en,wr_en,dmireset;

  rvjtag_tap
  i_jtag_tap
  (
    .trst(trst_n),
    .tck(tck),
    .tms(tms),
    .tdi(tdi),
    .tdo(tdo),
    .tdoEnable(tdoEnable),
    .wr_data(reg_wr_data),
    .wr_addr(reg_wr_addr),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .rd_data(rd_data),
    .rd_status({ 1'b0, 1'b0 }),
    .dmi_reset(dmireset),
    .dmi_hard_reset(dmi_hard_reset),
    .idle({ 1'b0, 1'b0, 1'b0 }),
    .dmi_stat({ 1'b0, 1'b0 }),
    .jtag_id(jtag_id),
    .version({ 1'b0, 1'b0, 1'b0, 1'b1 })
  );


  dmi_jtag_to_core_sync
  i_dmi_jtag_to_core_sync
  (
    .rd_en(rd_en),
    .wr_en(wr_en),
    .rst_n(core_rst_n),
    .clk(core_clk),
    .reg_en(reg_en),
    .reg_wr_en(reg_wr_en)
  );


