module rvdff_WIDTH10
(
  din,
  clk,
  rst_l,
  dout
);

  input [9:0] din;
  output [9:0] dout;
  input clk;
  input rst_l;
  wire N0;
  reg [9:0] dout;

  always @(posedge clk or posedge N0) begin
    if(N0) begin
      dout[9] <= 1'b0;
    end else if(1'b1) begin
      dout[9] <= din[9];
    end
  end


  always @(posedge clk or posedge N0) begin
    if(N0) begin
