module rvdff_WIDTH7
(
  din,
  clk,
  rst_l,
  dout
);

  input [6:0] din;
  output [6:0] dout;
  input clk;
  input rst_l;
  wire N0;
  reg [6:0] dout;

  always @(posedge clk or posedge N0) begin
    if(N0) begin
      dout[6] <= 1'b0;
    end else if(1'b1) begin
      dout[6] <= din[6];
    end
  end


  always @(posedge clk or posedge N0) begin
    if(N0) begin
      dout[5] <= 1'b0;
    end else if(1'b1) begin
      dout[5] <= din[5];
