  output [1:0] dout;
  input en;
  input clear;
  input clk;
  input rst_l;
  wire [1:0] dout,din_new;
  wire N0,N1,N2,N3,N4,N5;

  rvdff_WIDTH2
  dffsc
  (
    .din(din_new),
    .clk(clk),
    .rst_l(rst_l),
    .dout(dout)
  );

  assign { N4, N3 } = (N0)? din :
                      (N1)? dout : 1'b0;
  assign N0 = en;
  assign N1 = N2;
  assign N2 = ~en;
  assign din_new[1] = N5 & N4;
  assign N5 = ~clear;
  assign din_new[0] = N5 & N3;

endmodule



